/**
 * List all CommEvent records
 */
export async function getCommEventList(args: { data: { userId?: string; where?: Record<string, unknown> } }): Promise<CommEventType[]> {
  const params = new URLSearchParams()
  if (args.data.userId) params.set('userId', args.data.userId)
  if (args.data.where) {
    for (const [key, value] of Object.entries(args.data.where)) {
      if (value !== undefined && value !== null) params.set(key, String(value))
    }
  }
  const qs = params.toString()
  const url = `${getApiBase()}/api/comm-events${qs ? `?${qs}` : ''}`
  const response = await fetch(url)
  if (!response.ok) {
    const err = await response.json().catch(() => ({ error: { message: response.statusText } }))
    throw new Error(err.error?.message || 'Failed to list CommEvent')
  }
  const json = await response.json()
  return (json.items || []) as CommEventType[]
}

